<?php
session_start();if(empty($_SESSION['admin'])){header('Location: login.php');exit;}require __DIR__.'/config/db.php';
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
try{$rows=$pdo->query('SELECT * FROM notifications ORDER BY id DESC LIMIT 100')->fetchAll();$total=(int)$pdo->query('SELECT COUNT(*) FROM notifications')->fetchColumn();$appCount=(int)$pdo->query('SELECT COUNT(*) FROM apps')->fetchColumn();$deviceCount=(int)$pdo->query('SELECT COUNT(*) FROM devices')->fetchColumn();$today=(int)$pdo->query('SELECT COUNT(*) FROM notifications WHERE received_at>=CURDATE()')->fetchColumn();}catch(Throwable $e){$rows=[];$total=$appCount=$deviceCount=$today=0;}$last=$rows?(int)$rows[0]['id']:0;
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#ffffff"><title>NotifyBridge V5.0</title><link rel="stylesheet" href="assets/style.css"></head><body><div class="app"><aside class="side"><div class="brand"><div class="brand-logo">NB</div><div><b>NotifyBridge</b><small>CONTROL CENTER · V5.0</small></div></div><nav class="nav"><a class="active" href="#home">⌂ الرئيسية</a><a href="#feed">🔔 الإشعارات</a><a href="api-manager.php">🔑 إدارة API</a></nav><div class="side-bottom"><div class="health"><span class="dot"></span><b>النظام يعمل</b><small style="display:block;margin-top:5px;color:#7b96a6">مراقبة مباشرة للإشعارات</small></div><a class="logout" href="logout.php">تسجيل الخروج</a></div></aside><div class="main"><header class="top"><div style="display:flex;align-items:center;gap:10px"><button id="menuBtn" class="btn soft menu" type="button">☰</button><div><small class="eyebrow">NOTIFYBRIDGE</small><h1>لوحة التحكم الرئيسية</h1></div></div><div class="top-actions"><button id="desktopBtn" class="btn soft" type="button">🔔 إشعارات Windows</button><span id="liveStatus" class="badge"><span class="dot"></span> متصل</span></div></header><main id="home" class="content"><section class="hero"><div><span class="eyebrow">LIVE NOTIFICATION BRIDGE</span><h2>مركز إشعارات ذكي، سريع وواضح.</h2><p>تابع إشعارات هاتفك لحظة بلحظة، راقب الأجهزة والتطبيقات، اختبر الاتصال وأدر مفاتيح API من تجربة موحّدة مصممة لتجربة استخدام سريعة وواضحة.</p><div style="display:flex;gap:10px;flex-wrap:wrap"><a class="btn primary" style="text-decoration:none" href="#feed">عرض الإشعارات</a><button id="testBtn" class="btn soft" type="button">إرسال إشعار تجريبي</button></div></div><div class="hero-art"><div class="phone-visual"><span>NB</span><i></i><b>LIVE</b></div></div></section><section id="stats" class="stats"><article class="stat"><div class="stat-icon">🔔</div><div><span>إجمالي الإشعارات</span><strong id="totalStat"><?=$total?></strong><small>سجل محفوظ</small></div></article><article class="stat"><div class="stat-icon">▦</div><div><span>التطبيقات</span><strong><?=$appCount?></strong><small>مصادر مسجلة</small></div></article><article class="stat"><div class="stat-icon">📱</div><div><span>الأجهزة</span><strong><?=$deviceCount?></strong><small>أجهزة مرتبطة</small></div></article><article class="stat"><div class="stat-icon">☀</div><div><span>اليوم</span><strong><?=$today?></strong><small>إشعارات اليوم</small></div></article></section><section class="grid"><section class="panel" id="feed"><div class="panel-head"><div><span class="eyebrow">LIVE FEED</span><h2>الإشعارات المباشرة</h2></div><small id="pollText">تحديث تلقائي كل 3 ثوانٍ</small></div><div class="toolbar"><label class="search">⌕ <input id="searchInput" placeholder="ابحث باسم التطبيق أو محتوى الإشعار..."></label><button id="clearSearch" class="btn soft" type="button">مسح</button></div><div id="noticeList" class="notice-list"><?php if(!$rows):?><div id="empty" class="empty">🔔<h3>بانتظار أول إشعار</h3><p>سيظهر الإشعار هنا تلقائيًا عند وصوله.</p></div><?php endif?><?php foreach($rows as $r):$nm=$r['app_name']?:$r['app_package'];?><article class="notice" data-search="<?=h(mb_strtolower($nm.' '.$r['title'].' '.$r['message']))?>"><div class="avatar"><?=h(mb_substr($nm,0,1))?></div><div class="notice-main"><div class="notice-meta"><b><?=h($nm)?></b><time><?=h($r['received_at'])?></time></div><h3><?=h($r['title']?:'بدون عنوان')?></h3><p><?=nl2br(h($r['message']))?></p><small><?=h($r['device_id'])?> · <?=h($r['app_package'])?></small></div></article><?php endforeach?></div></section><aside><section class="panel connection" id="connection"><span class="eyebrow">CONNECTION</span><div class="orb">✓</div><h2 id="serverTitle">متصل بالخادم</h2><p id="serverText">جاهز لاستقبال الإشعارات</p><button id="healthBtn" class="btn primary" type="button">اختبار الاتصال الآن</button></section><section class="panel mini"><span class="eyebrow">QUICK ACTIONS</span><h2>إجراءات سريعة</h2><div class="activity"><span>🔑</span><div><b>مفاتيح API</b><small><a href="api-manager.php" style="color:#0b9ed8">فتح مركز إدارة API</a></small></div></div><div class="activity"><span>🖥️</span><div><b>إشعارات Windows</b><small id="desktopState">بانتظار الفحص</small></div></div></section></aside></section></main><footer class="footer"><div class="footer-brand"><div class="footer-mark">NB</div><div><strong>NotifyBridge</strong><small>Notification Control Center · V5.0</small></div></div><div class="footer-copy"><b>جميع حقوق التطوير والتصميم : محمد القرعان</b></div><div class="social-icons"><a class="social-icon" href="https://www.facebook.com/elqdes" target="_blank" rel="noopener" aria-label="Facebook @elqdes"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M13.6 22v-9h3l.45-3.5H13.6V7.25c0-1.01.28-1.7 1.73-1.7h1.87V2.42c-.32-.04-1.43-.14-2.72-.14-2.69 0-4.53 1.64-4.53 4.66V9.5H6.9V13h3.05v9z"/></svg></a><a class="social-icon" href="https://www.instagram.com/elqdes/" target="_blank" rel="noopener" aria-label="Instagram @elqdes"><svg viewBox="0 0 24 24" aria-hidden="true"><path fill-rule="evenodd" d="M7 2h10a5 5 0 0 1 5 5v10a5 5 0 0 1-5 5H7a5 5 0 0 1-5-5V7a5 5 0 0 1 5-5zm0 2a3 3 0 0 0-3 3v10a3 3 0 0 0 3 3h10a3 3 0 0 0 3-3V7a3 3 0 0 0-3-3H7zm5 3a5 5 0 1 1 0 10 5 5 0 0 1 0-10zm0 2a3 3 0 1 0 0 6 3 3 0 0 0 0-6zm5.6-3.5a1.2 1.2 0 1 1 0 2.4 1.2 1.2 0 0 1 0-2.4z"/></svg></a></div></footer></div></div><div id="toast" class="toast" role="status" aria-live="polite"></div><script>
(()=>{'use strict';let last=<?=$last?>,total=<?=$total?>,busy=false,timer=null,delay=3000;const $=s=>document.querySelector(s),list=$('#noticeList'),toast=$('#toast');function say(t){toast.textContent=t;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2600)}function esc(s){const d=document.createElement('div');d.textContent=String(s??'');return d.innerHTML}function updateDesktop(){const s=$('#desktopState'),b=$('#desktopBtn');if(!('Notification'in window)){s.textContent='غير مدعوم';b.disabled=true;return}const p=Notification.permission;s.textContent=p==='granted'?'مفعلة ✓':p==='denied'?'مرفوضة من المتصفح':'غير مفعلة';b.textContent=p==='granted'?'🔔 مفعلة ✓':'🔔 إشعارات Windows'}async function desktop(){if(!('Notification'in window))return say('المتصفح لا يدعم إشعارات سطح المكتب');try{await Notification.requestPermission();updateDesktop();say(Notification.permission==='granted'?'تم تفعيل إشعارات Windows':'لم يتم منح الصلاحية')}catch(e){say('تعذر طلب الصلاحية')}}function desktopNotify(n){if('Notification'in window&&Notification.permission==='granted'){try{new Notification(n.app_name||'NotifyBridge',{body:[n.title,n.message].filter(Boolean).join(' — '),tag:'amv-'+n.id})}catch(e){}}}function add(n){if(+n.id<=last)return;last=Math.max(last,+n.id);$('#empty')?.remove();const a=document.createElement('article');a.className='notice';a.dataset.search=((n.app_name||'')+' '+(n.title||'')+' '+(n.message||'')).toLowerCase();a.innerHTML='<div class="avatar">'+esc((n.app_name||n.app_package||'?').charAt(0))+'</div><div class="notice-main"><div class="notice-meta"><b>'+esc(n.app_name||n.app_package)+'</b><time>'+esc(n.received_at)+'</time></div><h3>'+esc(n.title||'بدون عنوان')+'</h3><p>'+esc(n.message||'')+'</p><small>'+esc(n.device_id)+' · '+esc(n.app_package)+'</small></div>';list.prepend(a);$('#totalStat').textContent=++total;desktopNotify(n)}function schedule(){clearTimeout(timer);timer=setTimeout(poll,delay)}async function poll(){if(busy)return schedule();busy=true;try{const r=await fetch('api/latest.php?after='+encodeURIComponent(last)+'&_='+Date.now(),{cache:'no-store',credentials:'same-origin'});if(r.status===401){location.href='login.php';return}if(!r.ok)throw new Error();const j=await r.json();if(!Array.isArray(j))throw new Error();j.forEach(add);$('#liveStatus').innerHTML='<span class="dot"></span> متصل';delay=3000}catch(e){$('#liveStatus').textContent='إعادة اتصال';delay=Math.min(delay*1.5,15000)}finally{busy=false;schedule()}}async function test(){const b=$('#testBtn');b.disabled=true;b.textContent='جاري الإرسال...';try{const r=await fetch('api/test-notification.php',{method:'POST',credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest'}});const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'failed');say('تم إنشاء إشعار تجريبي بنجاح ✓');setTimeout(poll,200)}catch(e){say('فشل الاختبار. تحقق من قاعدة البيانات وتسجيل الدخول.')}finally{b.disabled=false;b.textContent='إرسال إشعار تجريبي'}}async function health(){const b=$('#healthBtn');b.disabled=true;b.textContent='جاري الفحص...';try{const r=await fetch('api/health.php?_='+Date.now(),{cache:'no-store'}),j=await r.json();if(!r.ok||!j.ok)throw new Error();$('#serverTitle').textContent='متصل بالخادم ✓';$('#serverText').textContent='قاعدة البيانات تعمل بصورة سليمة';say('الاتصال سليم ✓')}catch(e){$('#serverTitle').textContent='تعذر الاتصال';$('#serverText').textContent='تحقق من إعدادات قاعدة البيانات والاستضافة';say('فشل اختبار الاتصال')}finally{b.disabled=false;b.textContent='اختبار الاتصال الآن'}}function filter(){const q=$('#searchInput').value.trim().toLowerCase();document.querySelectorAll('.notice').forEach(x=>x.hidden=!x.dataset.search.includes(q))}$('#menuBtn').addEventListener('click',()=>document.body.classList.toggle('nav-open'));$('#desktopBtn').addEventListener('click',desktop);$('#testBtn').addEventListener('click',test);$('#healthBtn').addEventListener('click',health);$('#searchInput').addEventListener('input',filter);$('#clearSearch').addEventListener('click',()=>{$('#searchInput').value='';filter()});updateDesktop();poll();})();
</script></body></html>
